<div class="container py-4">
    <h1 class="h3">Treatment source catalog</h1>
    <p class="text-muted">Bibliographic versions are shared across treatment systems. Your editorial capabilities apply through scope #<?= (int)$systemId ?>. Verification checks provenance; it does not establish treatment effectiveness.</p>
    <div class="d-flex gap-2 mb-3"><a class="btn btn-outline-secondary" href="<?= e(url('admin/treatments')) ?>">Treatment editorial</a><?php if ($canCreate): ?><a class="btn btn-primary" href="<?= e(url('admin/treatment-sources/'.$systemId.'/create')) ?>">Create source</a><?php endif; ?></div>
    <form method="get" action="<?= e(url('admin/treatment-sources/'.$systemId)) ?>" class="d-flex gap-2 mb-3"><label for="source-status" class="col-form-label">Status</label><select class="form-select w-auto" name="status" id="source-status"><option value="">All</option><?php foreach (['unverified','verified','withdrawn'] as $option): ?><option value="<?= e($option) ?>" <?= $status===$option ? 'selected' : '' ?>><?= e($option) ?></option><?php endforeach; ?></select><button class="btn btn-outline-primary">Filter</button></form>
    <div class="table-responsive"><table class="table table-striped"><caption>Immutable source records</caption><thead><tr><th>ID / title</th><th>Type</th><th>Status</th><th>Replaces</th></tr></thead><tbody><?php foreach ($sources as $s): ?><tr><td><a href="<?= e(url('admin/treatment-sources/'.$systemId.'/'.$s['id'])) ?>">#<?= (int)$s['id'] ?> <?= e($s['title']) ?></a></td><td><?= e(str_replace('_',' ',$s['source_type'])) ?></td><td><?= e($s['status']) ?></td><td><?= e((string)($s['replaces_source_id']??'—')) ?></td></tr><?php endforeach; ?><?php if (!$sources): ?><tr><td colspan="4">No sources match this filter.</td></tr><?php endif; ?></tbody></table></div>
    <nav aria-label="Source pages" class="d-flex gap-2"><?php if ($page>1): ?><a class="btn btn-outline-secondary" href="<?= e(url('admin/treatment-sources/'.$systemId).'?'.http_build_query(['status'=>$status??'','page'=>$page-1])) ?>">Previous</a><?php endif; ?><?php if ($more): ?><a class="btn btn-outline-secondary" href="<?= e(url('admin/treatment-sources/'.$systemId).'?'.http_build_query(['status'=>$status??'','page'=>$page+1])) ?>">Next</a><?php endif; ?></nav>
</div>
